package com.example.payment.integrationtest.paymentgateway;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.springframework.test.web.client.match.MockRestRequestMatchers.content;
import static org.springframework.test.web.client.match.MockRestRequestMatchers.header;
import static org.springframework.test.web.client.match.MockRestRequestMatchers.method;
import static org.springframework.test.web.client.match.MockRestRequestMatchers.requestTo;
import static org.springframework.test.web.client.response.MockRestResponseCreators.withStatus;
import static org.springframework.test.web.client.response.MockRestResponseCreators.withSuccess;

import com.example.payment.domain.AuthorizationOutcome;
import com.example.payment.domain.Money;
import com.example.payment.infrastructure.HttpPaymentGateway;
import java.math.BigDecimal;
import org.junit.jupiter.api.Test;
import org.springframework.http.HttpMethod;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.test.web.client.MockRestServiceServer;
import org.springframework.web.client.RestClient;

/**
 * Verifies that {@link HttpPaymentGateway} builds the request the provider expects and
 * correctly interprets every answer shape the provider can send back, without hitting a
 * real network endpoint.
 */
class HttpPaymentGatewayTest {

    private final RestClient.Builder builder = RestClient.builder().baseUrl("https://provider.example.com");
    private final MockRestServiceServer server = MockRestServiceServer.bindTo(builder).build();
    private final HttpPaymentGateway gateway = new HttpPaymentGateway(builder.build());

    @Test
    void sends_the_reference_and_amount_as_json() {
        server.expect(requestTo("https://provider.example.com/v1/authorizations"))
                .andExpect(method(HttpMethod.POST))
                .andExpect(header("Content-Type", MediaType.APPLICATION_JSON_VALUE))
                .andExpect(content().json("""
                        {"reference":"ORD-1","amount":42.50,"currency":"EUR"}
                        """))
                .andRespond(withSuccess("""
                        {"status":"approved"}
                        """, MediaType.APPLICATION_JSON));

        gateway.authorize("ORD-1", new Money(new BigDecimal("42.50"), "EUR"));

        server.verify();
    }

    @Test
    void an_approved_response_is_read_back_as_approved() {
        server.expect(requestTo("https://provider.example.com/v1/authorizations"))
                .andRespond(withSuccess("""
                        {"status":"approved"}
                        """, MediaType.APPLICATION_JSON));

        var outcome = gateway.authorize("ORD-2", new Money(BigDecimal.TEN, "EUR"));

        assertThat(outcome).isEqualTo(AuthorizationOutcome.APPROVED);
    }

    @Test
    void a_declined_response_is_read_back_as_declined() {
        server.expect(requestTo("https://provider.example.com/v1/authorizations"))
                .andRespond(withSuccess("""
                        {"status":"declined"}
                        """, MediaType.APPLICATION_JSON));

        var outcome = gateway.authorize("ORD-3", new Money(BigDecimal.TEN, "EUR"));

        assertThat(outcome).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void a_402_refusal_is_read_back_as_declined() {
        server.expect(requestTo("https://provider.example.com/v1/authorizations"))
                .andRespond(withStatus(HttpStatus.PAYMENT_REQUIRED));

        var outcome = gateway.authorize("ORD-4", new Money(BigDecimal.TEN, "EUR"));

        assertThat(outcome).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void an_unexpected_status_from_the_provider_is_reported_as_a_failure() {
        server.expect(requestTo("https://provider.example.com/v1/authorizations"))
                .andRespond(withStatus(HttpStatus.INTERNAL_SERVER_ERROR));

        assertThatThrownBy(() -> gateway.authorize("ORD-5", new Money(BigDecimal.TEN, "EUR")))
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("500");
    }

    @Test
    void a_body_with_neither_approved_nor_declined_is_treated_as_declined() {
        server.expect(requestTo("https://provider.example.com/v1/authorizations"))
                .andRespond(withSuccess("""
                        {"status":"pending"}
                        """, MediaType.APPLICATION_JSON));

        var outcome = gateway.authorize("ORD-6", new Money(BigDecimal.TEN, "EUR"));

        assertThat(outcome).isEqualTo(AuthorizationOutcome.DECLINED);
    }
}

